/* GPS tracks use field-clock time. Tracks and matches stay in the browser. */
function gpsDistance(a,b){const rad=Math.PI/180,dlat=(b.latitude-a.latitude)*rad,dlon=(b.longitude-a.longitude)*rad,h=Math.sin(dlat/2)**2+Math.cos(a.latitude*rad)*Math.cos(b.latitude*rad)*Math.sin(dlon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
function gpsMedian(values){const xs=values.filter(Number.isFinite).sort((a,b)=>a-b);return xs.length?(xs[Math.floor((xs.length-1)/2)]+xs[Math.ceil((xs.length-1)/2)])/2:null}
function gpsColumns(row){return Object.fromEntries(Object.entries(row).map(([key,value])=>[key.toLowerCase().replace(/[^a-z0-9]/g,''),value]))}
function isGPSTrack(rows){return rows.length&&rows.every(row=>row.id===undefined||String(row.id).trim()==='')&&rows.some(row=>{const c=gpsColumns(row);return(c.time!==undefined||c.timestamp!==undefined||c.datetime!==undefined)&&c.latitude!==undefined&&c.longitude!==undefined})}
function parseGPSTrack(rows){let invalid=0,preRecording=0;const points=[];for(const raw of rows){const r=gpsColumns(raw);if(Number.isFinite(Number(r.secondselapsed))&&Number(r.secondselapsed)<0){preRecording++;continue}const latitude=Number(r.latitude),longitude=Number(r.longitude);if(r.latitude===''||r.longitude===''||!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180){invalid++;continue}const value=r.timestamp??r.datetime??r.time;let t,utc=true;if(value!==''&&Number.isFinite(Number(value))&&Math.abs(Number(value))>1e8){const n=Number(value),abs=Math.abs(n);t=n/(abs>1e17?1e9:abs>1e14?1e6:abs>1e11?1e3:1)}else{const text=String(value||'').trim();if(r.date&&/^\d{1,2}:\d{2}/.test(text)){try{t=stamp(fieldDate(r.date,$('dateOrder').value)+' '+fieldClock(text));utc=false}catch(e){t=NaN}}else if(/(?:Z|[+-]\d{2}:?\d{2})$/i.test(text))t=Date.parse(text)/1000;else{t=stamp(text);utc=false}}if(!Number.isFinite(t)){invalid++;continue}const accuracy=Number(r.horizontalaccuracy??r.accuracy),speed=Number(r.speed);points.push({t,utc,latitude,longitude,accuracy:Number.isFinite(accuracy)&&accuracy>=0?accuracy:null,speed:r.speed!==undefined&&Number.isFinite(speed)&&speed>=0?speed:null})}points.sort((a,b)=>a.t-b.t);if(!points.length)throw Error('No valid GPS fixes with timestamps and coordinates were found.');return{points,invalid,preRecording}}
function gpsSettings(){const settings={offset:Number($('gpsUtcOffset').value),radius:Number($('gpsStopRadius').value),minDwell:Number($('gpsMinDwell').value),maxAccuracy:Number($('gpsMaxAccuracy').value),maxSpeed:Number($('gpsMaxSpeed').value)};if(!Number.isFinite(settings.offset)||settings.offset< -14||settings.offset>14||!Number.isFinite(settings.radius)||settings.radius<=0||!Number.isFinite(settings.minDwell)||settings.minDwell<=0||!Number.isFinite(settings.maxAccuracy)||settings.maxAccuracy<=0||!Number.isFinite(settings.maxSpeed)||settings.maxSpeed<0)throw Error('Check GPS offset, stop radius, dwell time, accuracy and speed settings.');return settings}
function loadGPSTrackControls(){const project=projects.find(p=>p.name===activeProject),cfg=project?.gpsSettings||{offset:2,radius:15,minDwell:60,maxAccuracy:25,maxSpeed:.5};for(const[key,id]of [['offset','gpsUtcOffset'],['radius','gpsStopRadius'],['minDwell','gpsMinDwell'],['maxAccuracy','gpsMaxAccuracy'],['maxSpeed','gpsMaxSpeed']])$(id).value=cfg[key]}
function gpsDwells(track,cfg){const fixes=track.points.map(p=>({...p,t:p.t+(p.utc?cfg.offset*3600:0)}));const dwells=[];let group=[];const finish=()=>{if(group.length>=3&&group.at(-1).t-group[0].t>=cfg.minDwell)dwells.push({start:group[0].t,end:group.at(-1).t,points:group});group=[]};let excluded=0;for(const p of fixes){if(p.accuracy!==null&&p.accuracy>cfg.maxAccuracy||p.speed!==null&&p.speed>cfg.maxSpeed){finish();excluded++;continue}if(group.length&&(p.t-group.at(-1).t>10||gpsDistance(group[0],p)>cfg.radius))finish();group.push(p)}finish();return{dwells,fixes,excluded}}
function recomputeProjectGPS(projectName,force=false){const project=projects.find(p=>p.name===projectName);if(!project?.gpsTracks?.length)return;const cfg=project.gpsSettings||gpsSettings(),prepared=project.gpsTracks.map(track=>({track,...gpsDwells(track,cfg)}));const report=[];for(const r of readings.filter(r=>r.project===projectName)){if(r.gpsMatchMethod==='id'&&!force)continue;const clock=measurementClock(r);let reason='',winner;if(!Number.isFinite(clock.start))reason='Field-condition date/time is needed before this track can be matched.';else{const candidates=[];for(const item of prepared)for(const dwell of item.dwells){const overlap=Math.max(0,Math.min(clock.end,dwell.end)-Math.max(clock.start,dwell.start)),fixes=dwell.points.filter(p=>p.t>=clock.start&&p.t<=clock.end);if(overlap>=Math.min(cfg.minDwell,clock.duration*.5)&&fixes.length>=3)candidates.push({item,dwell,overlap,fixes})}candidates.sort((a,b)=>b.overlap-a.overlap);if(!candidates.length)reason='No stationary GPS period overlaps this measurement with enough usable fixes. Check date/UTC offset, coverage and stop settings.';else if(candidates[1]&&candidates[1].overlap>=candidates[0].overlap*.8)reason='More than one stationary period has similar overlap; no location was guessed.';else winner=candidates[0]}
 if(winner){const latitude=gpsMedian(winner.fixes.map(p=>p.latitude)),longitude=gpsMedian(winner.fixes.map(p=>p.longitude)),centre={latitude,longitude},spread=Math.max(...winner.fixes.map(p=>gpsDistance(centre,p))),accuracy=gpsMedian(winner.fixes.map(p=>p.accuracy)),coverage=winner.overlap/clock.duration;r.latitude=latitude;r.longitude=longitude;r.gpsUploadName=winner.item.track.name;r.gpsAccuracyM=accuracy;r.gpsSpreadM=spread;r.gpsOverlapFraction=coverage;r.gpsMatchMethod='track';r.gpsTrackName=winner.item.track.name;r.gpsMatchNote=`Estimated from stationary track: ${winner.fixes.length} fixes, ${Math.round(winner.overlap)} s overlap (${Math.round(coverage*100)}% of the measurement), spread ${spread.toFixed(1)} m, median reported accuracy ${accuracy===null?'unavailable':accuracy.toFixed(1)+' m'}. Field-clock UTC offset ${cfg.offset>=0?'+':''}${cfg.offset} h. ${coverage<.8?'Partial coverage: review this location.':'Review the estimated location before reporting.'}`;report.push({id:r.id,status:'Matched · estimated',note:r.gpsMatchNote})}else{if(r.gpsMatchMethod==='track'){r.latitude='';r.longitude='';r.gpsUploadName='';r.gpsAccuracyM=null;r.gpsSpreadM=null;r.gpsOverlapFraction=null}r.gpsMatchNote=reason;report.push({id:r.id,status:hasGPS(r)?'Previous location retained':'Unmatched',note:reason})}}
 project.gpsTrackReport={rows:report,matched:report.filter(p=>p.status==='Matched · estimated').length,tracks:prepared.map(item=>({name:item.track.name,fixes:item.fixes.length,stops:item.dwells.length,excluded:item.excluded,start:clockStamp(item.fixes[0]?.t),end:clockStamp(item.fixes.at(-1)?.t)}))};}
async function importGPSTrack(rows,file){const project=projects.find(p=>p.name===activeProject);if(!project)throw Error('Select a project first.');const parsed=parseGPSTrack(rows),cfg=gpsSettings();project.gpsSettings=cfg;project.gpsTracks=project.gpsTracks||[];project.gpsTracks=project.gpsTracks.filter(track=>track.name!==file.name);project.gpsTracks.push({name:file.name,...parsed});recomputeProjectGPS(activeProject,true);await save();populate();$('status').textContent=`GPS track uploaded: ${file.name}. ${parsed.points.length.toLocaleString()} fixes retained; ${project.gpsTrackReport.matched} measurements matched to stationary periods. Unmatched readings are kept without guessed locations. See the GPS matching report.`;}
function renderGPSTrackReport(){const project=projects.find(p=>p.name===activeProject),report=project?.gpsTrackReport,tracks=project?.gpsTracks||[];$('rematchGPS').disabled=!activeProject||!tracks.length;$('gpsTrackStatus').textContent=tracks.length?`${tracks.length} location track(s) saved · ${report?.matched||0} stationary-period matches. Timestamps are converted from UTC to your field clock using the offset below.`:'Location tracks do not need IDs. Upload a track before or after conditions; it will be matched when field measurement times are available.';const panel=$('gpsMatchReport');panel.hidden=!tracks.length;panel.innerHTML=tracks.length?`<summary>GPS matching report</summary><p class="muted">${(report?.tracks||[]).map(t=>`${esc(t.name)}: ${t.fixes} fixes, ${t.stops} stationary periods; ${esc(t.start)} → ${esc(t.end)} on the field clock; ${t.excluded} fixes excluded by movement/accuracy settings.`).join('<br>')}</p><div style="overflow:auto"><table><thead><tr><th>Reading</th><th>Match</th><th>Evidence / reason</th></tr></thead><tbody>${(report?.rows||[]).map(row=>`<tr><td>${esc(row.id)}</td><td>${esc(row.status)}</td><td style="white-space:normal">${esc(row.note)}</td></tr>`).join('')}</tbody></table></div>`:'';}
async function rematchGPSTracks(){try{const project=projects.find(p=>p.name===activeProject);if(!project)return;project.gpsSettings=gpsSettings();recomputeProjectGPS(activeProject,true);await save();populate();$('status').textContent='GPS stationary-period matching updated. Review the matching report.'}catch(error){$('status').textContent='GPS matching: '+error.message}}
